111	    @Override
112	    public void handle(RestClientRequestContext requestContext) {
113	        if (requestContext.isAborted()) {
114	            return;
115	        }
116	        requestContext.suspend();
117	
118	        requestContext.setHttpClientOptions(httpClientOptions);
119	
120	        Uni<HttpClientRequest> future = createRequest(requestContext);
121	
122	        // DNS failures happen before we send the request
123	        future.subscribe().with(new Consumer<>() {
124	            @Override
125	            public void accept(HttpClientRequest httpClientRequest) {
126	                if (requestContext.isUserCanceled()) {
127	                    // in this case the user aborted before the request was even created
128	                    return;
129	                }
130	
131	                customizeRequest(httpClientRequest, requestContext);
132	
133	                // adapt headers to HTTP/2 depending on the underlying HTTP connection
134	                ClientSendRequestHandler.this.adaptRequest(httpClientRequest);
135	
136	                if (requestContext.isMultipart()) {
137	                    Promise<HttpClientRequest> requestPromise = Promise.promise();
138	                    QuarkusMultipartFormUpload actualEntity;
139	                    try {
140	                        actualEntity = ClientSendRequestHandler.this.setMultipartHeadersAndPrepareBody(httpClientRequest,
141	                                requestContext);
142	                        if (loggingScope != LoggingScope.NONE) {
143	                            clientLogger.logRequest(httpClientRequest, null, true);
144	                        }
145	
146	                        Pipe<Buffer> pipe = actualEntity.pipe(); // Shouldn't this be called in an earlier phase ?
147	                        requestPromise.future().onComplete(ar -> {
148	
149	                            if (ar.succeeded()) {
150	                                HttpClientRequest req = ar.result();
151	                                if (httpClientRequest.headers() == null
152	                                        || !httpClientRequest.headers().contains(HttpHeaders.CONTENT_LENGTH)) {
153	                                    req.setChunked(true);
154	                                }
155	                                pipe.endOnFailure(false);
156	                                pipe.to(req).onComplete(ar2 -> {
157	                                    if (ar2.failed()) {
158	                                        req.reset(0L, ar2.cause());
159	                                    }
160	                                });
161	                                actualEntity.run();
162	                            } else {
163	                                pipe.close();
164	                            }
165	                        });
166	                        Future<HttpClientResponse> sent = httpClientRequest.response();
167	                        requestPromise.complete(httpClientRequest);
168	                        attachSentHandlers(sent, httpClientRequest, requestContext);
169	                    } catch (Throwable e) {
170	                        reportFinish(e, requestContext);
171	                        requestContext.resume(e);
172	                        return;
173	                    }
174	                } else if (requestContext.isFileUpload()) {
175	                    Vertx vertx = Vertx.currentContext().owner();
176	                    Object entity = requestContext.getEntity().getEntity();
177	                    String filePathToUpload = null;
178	                    if (entity instanceof File) {
179	                        filePathToUpload = ((File) entity).getAbsolutePath();
180	                    } else if (entity instanceof Path) {
181	                        filePathToUpload = ((Path) entity).toAbsolutePath().toString();
182	                    }
183	                    vertx.fileSystem()
184	                            .open(filePathToUpload, new OpenOptions().setRead(true).setWrite(false))
185	                            .onComplete(openedAsyncFile -> {
186	                                if (openedAsyncFile.failed()) {
187	                                    requestContext.resume(openedAsyncFile.cause());
188	                                    return;
189	                                }
190	
191	                                MultivaluedMap<String, String> headerMap = requestContext.getRequestHeadersAsMap();
192	                                updateRequestHeadersFromConfig(requestContext, headerMap);
193	                                setEntityRelatedHeaders(headerMap, requestContext.getEntity());
194	
195	                                // set the Vertx headers after we've run the interceptors because they can modify them
196	                                setVertxHeaders(httpClientRequest, headerMap);
197	
198	                                Future<HttpClientResponse> sent = httpClientRequest.send(openedAsyncFile.result());
199	                                attachSentHandlers(sent, httpClientRequest, requestContext);
200	                            });
201	                } else if (requestContext.isInputStreamUpload() && !hasWriterInterceptors(requestContext)) {
202	                    MultivaluedMap<String, String> headerMap = requestContext.getRequestHeadersAsMap();
203	                    updateRequestHeadersFromConfig(requestContext, headerMap);
204	                    setEntityRelatedHeaders(headerMap, requestContext.getEntity());
205	                    setVertxHeaders(httpClientRequest, headerMap);
206	                    Future<HttpClientResponse> sent = httpClientRequest.send(
207	                            new InputStreamReadStream(
208	                                    Vertx.currentContext().owner(), (InputStream) requestContext.getEntity().getEntity(),
209	                                    httpClientRequest, inputStreamChunkSize));
210	                    attachSentHandlers(sent, httpClientRequest, requestContext);
211	                } else if (requestContext.isMultiBufferUpload()) {
212	                    MultivaluedMap<String, String> headerMap = requestContext.getRequestHeadersAsMap();
213	                    updateRequestHeadersFromConfig(requestContext, headerMap);
214	                    setVertxHeaders(httpClientRequest, headerMap);
215	                    Multi<Buffer> buffers = ((Multi<?>) requestContext.getEntity().getEntity()).onItem()
216	                            .transform(ClientSendRequestHandler::toBuffer);
217	                    if (!httpClientRequest.headers().contains(HttpHeaders.CONTENT_LENGTH)) {
218	                        httpClientRequest.setChunked(true);
219	                    }
220	                    // a failing Multi must fail the request: with the default pipe behaviour the body would be ended
221	                    // normally and the server response to the truncated body would be reported as a success
222	                    ReadStream<Buffer> body = ReadStreamSubscriber.asReadStream(buffers,
223	                            new Function<>() {
224	                                @Override
225	                                public Buffer apply(Buffer buffer) {
226	                                    return buffer;
227	                                }
228	                            });
229	                    Pipe<Buffer> pipe = body.pipe();
230	                    pipe.endOnFailure(false);
231	                    pipe.to(httpClientRequest).onComplete(new Handler<>() {
232	                        @Override
233	                        public void handle(AsyncResult<Void> ar) {
234	                            if (ar.failed()) {
235	                                httpClientRequest.reset(0L, ar.cause());
236	                            }
237	                        }
238	                    });
239	                    Future<HttpClientResponse> sent = httpClientRequest.response();
240	                    attachSentHandlers(sent, httpClientRequest, requestContext);
241	                } else {
242	                    Future<HttpClientResponse> sent;
243	                    Buffer actualEntity;
244	                    try {
245	                        actualEntity = ClientSendRequestHandler.this
246	                                .setRequestHeadersAndPrepareBody(httpClientRequest, requestContext);
247	                    } catch (Throwable e) {
248	                        requestContext.resume(e);
249	                        return;
250	                    }
251	                    if (actualEntity == AsyncInvokerImpl.EMPTY_BUFFER) {
252	                        sent = httpClientRequest.send();
253	                        if (loggingScope != LoggingScope.NONE) {
254	                            clientLogger.logRequest(httpClientRequest, null, false);
255	                        }
256	                    } else {
257	                        sent = httpClientRequest.send(actualEntity);
258	                        if (loggingScope != LoggingScope.NONE) {
259	                            clientLogger.logRequest(httpClientRequest, actualEntity, false);
260	                        }
261	                    }
262	                    attachSentHandlers(sent, httpClientRequest, requestContext);
263	                }
264	            }
265	        }, new Consumer<>() {
266	            @Override
267	            public void accept(Throwable event) {
268	                // set some properties to prevent NPEs down the chain
269	                requestContext.setResponseHeaders(new MultivaluedTreeMap<>());
270	                requestContext.setResponseReasonPhrase("unknown");
271	
272	                if (event instanceof IOException) {
273	                    ProcessingException throwable = new ProcessingException(event);
274	                    reportFinish(throwable, requestContext);
275	                    requestContext.resume(throwable);
276	                } else {
277	                    requestContext.resume(event);
278	                    reportFinish(event, requestContext);
279	                }
280	            }
281	        });
282	    }
