284	    private void customizeRequest(HttpClientRequest httpClientRequest, RestClientRequestContext requestContext) {
285	        installRedirectRequestCustomizer(httpClientRequest, requestContext);
286	        for (int i = 0; i < clientRequestCustomizers.size(); i++) {
287	            clientRequestCustomizers.get(i).accept(httpClientRequest);
288	        }
289	
290	        requestContext.setHttpClientRequest(httpClientRequest);
291	    }
