293	    /*
294	     * If the request leads to a new request because of redirect then this method will install the original request's
295	     * customizers to the new redirect request.
296	     */
297	    private void installRedirectRequestCustomizer(HttpClientRequest httpClientRequest,
298	            RestClientRequestContext requestContext) {
299	        if (!followRedirects || clientRequestCustomizers.isEmpty()) {
300	            return;
301	        }
302	        httpClientRequest.redirectHandler(response -> {
303	            /*
304	             * The docs for `redirectHandler()` make no statement about whether the returned result is nullable.
305	             * We'll guard against null here and assume there's no redirect taking place.
306	             */
307	            Function<HttpClientResponse, Future<RequestOptions>> redirectHandler = ((HttpClientInternal) requestContext
308	                    .getHttpClient())
309	                    .redirectHandler();
310	            if (redirectHandler == null) {
311	                return Future.succeededFuture(null);
312	            }
313	
314	            /*
315	             * @see HttpClient#redirectHandler(Function)
316	             * According to the docs the `redirectHandler` function returns null if there is no redirect taking place.
317	             *
318	             * But it doesn't return `HttpClientRequest`, it returns a `Future<RequestOptions>`.
319	             * Vert.x 3 exposed redirect handling in terms of HttpClientRequest, while Vert.x 4
320	             * changed the client-level redirect handler to Future<RequestOptions>. The current
321	             * docs still describe the old null semantics, so they are likely stale.
322	             *
323	             * In practice, we defensively accept both interpretations of "no redirect":
324	             * - the handler returns a null Future<RequestOptions>
325	             * - the handler returns a Future completing with null RequestOptions
326	             */
327	            Future<RequestOptions> redirectOptions = redirectHandler.apply(response);
328	            if (redirectOptions == null) {
329	                return Future.succeededFuture(null);
330	            }
331	            return redirectOptions.compose(options -> {
332	                if (options == null) {
333	                    return Future.succeededFuture(null);
334	                }
335	                /*
336	                 * If there is a redirect taking place install the original request's customizers to the redirect
337	                 * request.
338	                 */
339	                return requestContext.getHttpClient().request(options)
340	                        .map(nextRequest -> {
341	                            customizeRequest(nextRequest, requestContext);
342	                            return nextRequest;
343	                        });
344	            });
345	        });
346	    }
