348	    private static Buffer toBuffer(Object item) {
349	        if (item instanceof Buffer buffer) {
350	            return buffer;
351	        }
352	        if (item instanceof byte[] bytes) {
353	            return Buffer.buffer(bytes);
354	        }
355	        throw new IllegalArgumentException("Unsupported item type '" + item.getClass().getName()
356	                + "' for a streamed request body. Supported types are io.vertx.core.buffer.Buffer and byte[]");
357	    }
