359	    private void attachSentHandlers(Future<HttpClientResponse> sent,
360	            HttpClientRequest httpClientRequest,
361	            RestClientRequestContext requestContext) {
362	        sent.onSuccess(new Handler<>() {
363	            @Override
364	            public void handle(HttpClientResponse clientResponse) {
365	                try {
366	                    requestContext.initialiseResponse(clientResponse);
367	                    int status = clientResponse.statusCode();
368	                    if (requestContext.getCallStatsCollector() != null) {
369	                        if (status >= 500 && status < 600) {
370	                            reportFinish(new InternalServerErrorException(),
371	                                    requestContext);
372	                        } else {
373	                            reportFinish(null, requestContext);
374	                        }
375	                    }
376	
377	                    if (isResponseMultipart(requestContext) && !requestContext.isInputStreamDownload()) {
378	                        QuarkusMultipartResponseDecoder multipartDecoder = new QuarkusMultipartResponseDecoder(
379	                                clientResponse);
380	
381	                        // Collect raw buffers so we can reconstruct an entity stream for MessageBodyReader usage
382	                        // (e.g. Response.readEntity with a custom reader), since the Netty decoder consumes the data
383	                        List<Buffer> rawBuffers = new ArrayList<>();
384	                        clientResponse.handler(buffer -> {
385	                            rawBuffers.add(buffer.copy());
386	                            multipartDecoder.offer(buffer);
387	                        });
388	
389	                        clientResponse.endHandler(new Handler<>() {
390	                            @Override
391	                            public void handle(Void event) {
392	                                multipartDecoder.offer(LastHttpContent.EMPTY_LAST_CONTENT);
393	
394	                                List<InterfaceHttpData> datas = multipartDecoder.getBodyHttpDatas();
395	                                requestContext.setResponseMultipartParts(datas);
396	
397	                                Buffer combined = Buffer.buffer();
398	                                for (Buffer b : rawBuffers) {
399	                                    combined.appendBuffer(b);
400	                                }
401	                                if (combined.length() > 0) {
402	                                    requestContext.setResponseEntityStream(
403	                                            new ByteArrayInputStream(combined.getBytes()));
404	                                }
405	
406	                                if (loggingScope != LoggingScope.NONE) {
407	                                    clientLogger.logResponse(clientResponse, false);
408	                                }
409	
410	                                requestContext.resume();
411	                            }
412	                        });
413	                    } else if (!requestContext.isRegisterBodyHandler()
414	                            && (Response.Status.Family.familyOf(status) == Response.Status.Family.SUCCESSFUL)) { // we force the registration of a body handler if there was an error, so we can ensure the body can be read
415	                        clientResponse.pause();
416	                        if (loggingScope != LoggingScope.NONE) {
417	                            clientLogger.logResponse(clientResponse, false);
418	                        }
419	                        requestContext.resume();
420	                    } else {
421	                        if (requestContext.isFileDownload()) {
422	                            // when downloading a file we copy the bytes to the file system and manually set the entity type
423	                            // this is needed because large files can cause OOM or exceed the InputStream limit (of 2GB)
424	
425	                            clientResponse.pause();
426	                            Vertx vertx = Vertx.currentContext().owner();
427	                            vertx.fileSystem().createTempFile("rest-client", "")
428	                                    .onComplete(tempFileCreation -> {
429	                                        if (tempFileCreation.failed()) {
430	                                            reportFinish(tempFileCreation.cause(), requestContext);
431	                                            requestContext.resume(tempFileCreation.cause());
432	                                            return;
433	                                        }
434	                                        String tmpFilePath = tempFileCreation.result();
435	                                        vertx.fileSystem().open(tmpFilePath,
436	                                                new OpenOptions().setWrite(true))
437	                                                .onComplete(asyncFileOpened -> {
438	                                                    if (asyncFileOpened.failed()) {
439	                                                        reportFinish(asyncFileOpened.cause(), requestContext);
440	                                                        requestContext.resume(asyncFileOpened.cause());
441	                                                        return;
442	                                                    }
443	                                                    final AsyncFile tmpAsyncFile = asyncFileOpened.result();
444	                                                    clientResponse.pipeTo(tmpAsyncFile)
445	                                                            .onComplete(event -> {
446	                                                                if (event.failed()) {
447	                                                                    reportFinish(event.cause(),
448	                                                                            requestContext);
449	                                                                    requestContext.resume(event.cause());
450	                                                                    return;
451	                                                                }
452	
453	                                                                if (loggingScope != LoggingScope.NONE) {
454	                                                                    clientLogger.logRequest(
455	                                                                            httpClientRequest, null, false);
456	                                                                }
457	
458	                                                                requestContext.setTmpFilePath(tmpFilePath);
459	                                                                requestContext.resume();
460	                                                            });
461	                                                    clientResponse.resume();
462	                                                });
463	                                    });
464	
465	                        } else if (requestContext.isInputStreamDownload() ||
466	                        // when returning Response (and not Uni<Response>) we don't buffer the result
467	                        // but instead set up the proper InputStream
468	                        // for Uni<Response> we can't buffer because setting up the InputSteam would result in blocking the event loop
469	                                (requestContext.isJakartaResponseDownload()
470	                                        && !requestContext.invokedMethodReturnsAsyncType())) {
471	                            if (loggingScope != LoggingScope.NONE) {
472	                                clientLogger.logResponse(clientResponse, false);
473	                            }
474	                            //TODO: make timeout configurable
475	                            requestContext
476	                                    .setResponseEntityStream(
477	                                            new VertxClientInputStream(clientResponse, 100000));
478	                            requestContext.resume();
479	                        } else {
480	                            clientResponse.body().onComplete(ar -> {
481	                                if (ar.succeeded()) {
482	                                    if (loggingScope != LoggingScope.NONE) {
483	                                        clientLogger.logResponse(clientResponse, false);
484	                                    }
485	                                    Buffer buffer = ar.result();
486	                                    try {
487	                                        if (buffer.length() > 0) {
488	                                            requestContext.setResponseEntityStream(
489	                                                    new ByteBufInputStream(
490	                                                            ((BufferInternal) buffer).getByteBuf(), true));
491	                                        } else {
492	                                            requestContext.setResponseEntityStream(null);
493	                                        }
494	                                        requestContext.resume();
495	                                    } catch (Throwable t) {
496	                                        requestContext.resume(t);
497	                                    }
498	                                } else {
499	                                    requestContext.resume(ar.cause());
500	                                }
501	                            });
502	                        }
503	                    }
504	                } catch (Throwable t) {
505	                    reportFinish(t, requestContext);
506	                    requestContext.resume(t);
507	                }
508	            }
509	        })
510	                .onFailure(new Handler<>() {
511	                    @Override
512	                    public void handle(Throwable failure) {
513	                        if (failure instanceof HttpClosedException || failure instanceof DecoderException) {
514	                            // This is because of the Rest Client TCK
515	                            // HttpClosedException / DecoderException are runtime exceptions. If we complete with that
516	                            // exception, it gets unwrapped by the rest client proxy and thus fails the TCK.
517	                            // By creating an IOException, we avoid that and provide a meaningful exception (because
518	                            // it's an I/O exception)
519	                            requestContext.resume(new ProcessingException(new IOException(failure.getMessage())));
520	                        } else if (failure instanceof IOException) {
521	                            requestContext.resume(new ProcessingException(failure));
522	                        } else {
523	                            requestContext.resume(failure);
524	                        }
525	                    }
526	                });
527	    }
