529	    private boolean isResponseMultipart(RestClientRequestContext requestContext) {
530	        MultivaluedMap<String, String> responseHeaders = requestContext.getResponseHeaders();
531	        List<String> contentTypes = responseHeaders.get(CONTENT_TYPE);
532	        if (contentTypes != null) {
533	            for (String contentType : contentTypes) {
534	                if (contentType.toLowerCase(Locale.ROOT).startsWith(MediaType.MULTIPART_FORM_DATA)) {
535	                    return true;
536	                }
537	            }
538	        }
539	        return false;
540	    }
