542	    private void reportFinish(Throwable throwable, RestClientRequestContext requestContext) {
543	        ServiceInstance serviceInstance = requestContext.getCallStatsCollector();
544	        if (serviceInstance != null) {
545	            serviceInstance.recordReply();
546	            serviceInstance.recordEnd(throwable);
547	        }
