550	    public Uni<HttpClientRequest> createRequest(RestClientRequestContext state) {
551	        HttpClient httpClient = state.getHttpClient();
552	        URI uri = state.getUri();
553	        Object readTimeout = state.getConfiguration().getProperty(QuarkusRestClientProperties.READ_TIMEOUT);
554	        Uni<RequestOptions> requestOptions;
555	        state.setMultipartResponsesData(multipartResponseDataMap);
556	        if (uri.getScheme() == null) { // invalid URI
557	            return Uni.createFrom()
558	                    .failure(new IllegalArgumentException("Invalid REST Client URL used: '" + uri + "'"));
559	        }
560	        try {
561	            URL ignored = uri.toURL();
562	        } catch (MalformedURLException mue) {
563	            log.error("Invalid REST Client URL used: '" + uri + "'");
564	            return Uni.createFrom()
565	                    .failure(new IllegalArgumentException("Invalid REST Client URL used: '" + uri + "'"));
566	        }
567	
568	        boolean isHttps = "https".equals(uri.getScheme());
569	        int port = getPort(isHttps, uri.getPort());
570	        requestOptions = Uni.createFrom().item(new RequestOptions().setHost(uri.getHost())
571	                .setPort(port).setSsl(isHttps));
572	
573	        if (domainSocketPath != null) {
574	            requestOptions = requestOptions.onItem().invoke(
575	                    new Consumer<RequestOptions>() {
576	                        @Override
577	                        public void accept(RequestOptions requestOptions) {
578	                            requestOptions.setServer(SocketAddress.domainSocketAddress(domainSocketPath));
579	                        }
580	                    });
581	        }
582	
583	        return requestOptions.onItem()
584	                .transform(r -> {
585	                    r.setMethod(HttpMethod.valueOf(state.getHttpMethod()))
586	                            .setURI(uri.getRawPath() + (uri.getRawQuery() == null ? "" : "?" + uri.getRawQuery()))
587	                            .setFollowRedirects(followRedirects);
588	                    String pathTemplate = (String) state.getClientFilterProperties().get("UrlPathTemplate");
589	                    if (pathTemplate != null && pathTemplate.length() > 1) {
590	                        r.setTraceOperation(state.getHttpMethod() + " " + pathTemplate);
591	                    }
592	                    return r;
593	                })
594	                .onItem().invoke(r -> {
595	                    if (readTimeout instanceof Long) {
596	                        r.setTimeout((Long) readTimeout);
597	                    }
598	                })
599	                .onItem().transformToUni(new Function<RequestOptions, Uni<? extends HttpClientRequest>>() {

